/** Every icon name resolvable by the NOX runtime registry. */
export const NOX_ICON_NAMES = ["app-grid","arrow-down","arrow-left","arrow-right","arrow-up","attachment","ban","bell","brand:kirel","brand:kirel-nox","brand:kirlet-demo","brand:kirlet-hr","brand:kirlet-tienda","brand:opus-perpetuus","briefcase","building","calendar","cart","check","check-square","chevron-down","chevron-left","chevron-right","chevron-up","clock","close","copy","counter","currency","dashboard","document","dots-horizontal","dots-vertical","download","edit","external-link","eye","eye-off","filter","history","home","info","key","link","lock","login","logout","logs","menu","minus","module","package","playground","plus","question","refresh","save","search","settings","sidebar-collapse","sidebar-expand","store","tag","trash","truck","unlock","upload","user","users","warning","x-square"] as const;

export type NoxIconName = (typeof NOX_ICON_NAMES)[number];

const NAME_SET: ReadonlySet<string> = new Set(NOX_ICON_NAMES);

/** True when `name` is a catalog icon (core or brand). */
export function is_nox_icon_name(name: string): name is NoxIconName {
  return NAME_SET.has(name);
}

/**
 * True for any reference the runtime can resolve: catalog names plus
 * kirlet-registered icons (`kirlet:<technical-id>`).
 */
export function is_valid_icon_ref(ref: string): boolean {
  if (NAME_SET.has(ref)) return true;
  return /^kirlet:[a-z][a-z0-9-]*$/.test(ref);
}

